"""Low level  interaction functions for the View Preset Selection window. The view can be the Planar/Motion View"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.xvi.xvi_types import ViewType, View_Preset_Selection
from interops.libraries.miscellaneous.decorators import log_decorator,LogMeta
from interops.libraries.xvi.interactions.common_objects_ops import  get_text, click_item, get_list_items

class ViewPresetSelectionOps(metaclass = LogMeta):
    '''
    The class is used to manupulate the Planar view and Motion view. And Volume view is currently not tested by this class as there is a separated module to handle it.
    '''
    def __init__(self, typeOfView: ViewType = ViewType.Unknown) -> None:
        obj = squishtest.waitForObjectExists(Xvi_MainPage.preset_Selection_Dialog)
        self._viewObj = obj
        self._view_preset_selection = View_Preset_Selection()
        _viewType = typeOfView
        if obj and typeOfView != ViewType.Unknown and typeOfView.name not in obj.text:
            raise Exception("This is not " + typeOfView.name)
        else:
            name = obj.text.split('-')[0].strip()
            _viewType = ViewType[name]
        self._view_preset_selection.viewtype = _viewType

    @property
    def view_type(self):
        return self._view_preset_selection.viewtype

    @property
    def acquisition_list(self):
        return get_list_items(Xvi_MainPage.preset_Selection_Acquisition_ComboBox)

    @property
    def acquisition(self):
        self._view_preset_selection.acquisition = get_text(Xvi_MainPage.preset_Selection_Acquisition_ComboBox)
        return self._view_preset_selection.acquisition

    @acquisition.setter
    def acquisition(self, value):
        click_item(Xvi_MainPage.preset_Selection_Acquisition_ComboBox, value)
        self._view_preset_selection.acquisition = value

    @property
    def description(self):
        self._view_preset_selection.description = get_text(Xvi_MainPage.preset_Selection_Description_Edit)
        return self._view_preset_selection.description

    @property
    def parameters(self):
        self._get_parameters()
        return self._view_preset_selection.parameters

    def click_Unconfirm_Setting_button(self):
        common.left_click_object(Xvi_MainPage.preset_Selection_Unconfirm_Settings_Button)

    def click_Confirm_Setting_button(self):
        common.left_click_object(Xvi_MainPage.preset_Selection_Confirm_Settings_Button)

    def click_View_Inhibits_button(self):
        common.left_click_object(Xvi_MainPage.preset_Selection_View_Inhibits_Button)

    def click_Cancel_button(self):
        common.left_click_object(Xvi_MainPage.preset_Selection_Cancel_Button)

    def _get_parameters(self):
        gantry_angle_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_Gantry_Angle_Label_0)
        kV_collimator_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_kV_Collimator_Label_0)
        kV_Filter_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_kV_Filter_Label_0)
        kV_Panel_Postion_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_kV_Panel_Position_Label_0)
        kV_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_kV_Label)
        frames_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_Frames_Label)
        total_mAs_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_Total_mAs_Label)
        nominal_dose_label = squishtest.waitForObject(Xvi_MainPage.preset_Selection_Nominal_Dose_Air_Kerma_Label)

        if self._viewObj:
            for obj in squishtest.object.children(self._viewObj):
                if getattr(obj, 'class', '') == '#32770':
                    for child in squishtest.object.children(obj):
                        if child.id in ('18001', '18002', '18005', '18006'):
                            if child.x < frames_label.x:
                                if child.id == '18001':
                                    rgba = get_center_pixel(child)
                                    intolerence = str(rgba[:3] != (255, 50, 50))
                                    if child.y == gantry_angle_label.y:
                                        self._view_preset_selection.parameters[gantry_angle_label.text]['In Tolerance'] = intolerence
                                    elif child.y == kV_collimator_label.y:
                                        self._view_preset_selection.parameters[kV_collimator_label.text]['In Tolerance'] = intolerence
                                    elif child.y == kV_Filter_label.y:
                                        self._view_preset_selection.parameters[kV_Filter_label.text]['In Tolerance'] = intolerence
                                    elif child.y == kV_Panel_Postion_label.y:
                                        self._view_preset_selection.parameters[kV_Panel_Postion_label.text]['In Tolerance'] = intolerence
                                elif child.id == '18005':
                                    if child.y == gantry_angle_label.y:
                                        self._view_preset_selection.parameters[gantry_angle_label.text]['SET'] = child.text
                                    elif child.y == kV_collimator_label.y:
                                        self._view_preset_selection.parameters[kV_collimator_label.text]['SET'] = child.text
                                    elif child.y == kV_Filter_label.y:
                                        self._view_preset_selection.parameters[kV_Filter_label.text]['SET'] = child.text
                                    elif child.y == kV_Panel_Postion_label.y:
                                        self._view_preset_selection.parameters[kV_Panel_Postion_label.text]['SET'] = child.text
                                elif child.id == '18006':
                                    if child.y == gantry_angle_label.y:
                                        self._view_preset_selection.parameters[gantry_angle_label.text]['ACTUAL'] = child.text
                                    elif child.y == kV_collimator_label.y:
                                        self._view_preset_selection.parameters[kV_collimator_label.text]['ACTUAL'] = child.text
                                    elif child.y == kV_Filter_label.y:
                                        self._view_preset_selection.parameters[kV_Filter_label.text]['ACTUAL'] = child.text
                                    elif child.y == kV_Panel_Postion_label.y:
                                        self._view_preset_selection.parameters[kV_Panel_Postion_label.text]['ACTUAL'] = child.text
                                elif child.id == '18002':
                                    if child.y == gantry_angle_label.y:
                                        self._view_preset_selection.parameters[gantry_angle_label.text]['Unit'] = child.text
                                    elif child.y == kV_collimator_label.y:
                                        self._view_preset_selection.parameters[kV_collimator_label.text]['Unit'] = child.text
                                    elif child.y == kV_Filter_label.y:
                                        self._view_preset_selection.parameters[kV_Filter_label.text]['Unit'] = child.text
                                    elif child.y == kV_Panel_Postion_label.y:
                                        self._view_preset_selection.parameters[kV_Panel_Postion_label.text]['Unit'] = child.text
                            else:
                                if child.id == '18005':
                                    if child.y == kV_label.y:
                                        self._view_preset_selection.parameters[kV_label.text]['SET'] = child.text
                                    elif child.y == frames_label.y:
                                        self._view_preset_selection.parameters[frames_label.text]['SET'] = child.text
                                    elif child.y == total_mAs_label.y:
                                        self._view_preset_selection.parameters[total_mAs_label.text]['SET'] = child.text
                                    elif child.y == nominal_dose_label.y:
                                        self._view_preset_selection.parameters[nominal_dose_label.text]['SET'] = child.text
                                elif child.id == '18002':
                                    if child.y == kV_label.y:
                                        self._view_preset_selection.parameters[kV_label.text]['Unit'] = child.text
                                    elif child.y == frames_label.y:
                                        self._view_preset_selection.parameters[frames_label.text]['Unit'] = child.text
                                    elif child.y == total_mAs_label.y:
                                        self._view_preset_selection.parameters[total_mAs_label.text]['Unit'] = child.text
                                    elif child.y == nominal_dose_label.y:
                                        self._view_preset_selection.parameters[nominal_dose_label.text]['Unit'] = child.text

@log_decorator
def get_center_pixel(obj):
    '''
    This function is used to get the center pixel of an object by grabbing a screenshot of it and then save/get/load the image.
    If there is a better way to get a pixel from a position of an object, this will be replaced.
    '''
    screenshot =  squishtest.grabWidget(obj)
    screenshot_path = '_screenshot_.png'
    screenshot.save(screenshot_path, 'PNG')
    squishtest.snooze(.1)
    squishtest.testData.get(screenshot_path)
    squishtest.snooze(.1)
    img = squishtest.Image.load(screenshot_path)
    rgba = img.getPixelRGBA(img.width/2, img.height/2)
    return rgba

@log_decorator
def click_kV_view_button(viewType:ViewType):
    '''
    Click one of the buttons of PlanarView, MotionView, VolumeView, but note that the UI of VolumeView is different from the other two a little bit.
    '''
    if viewType == ViewType.PlanarView:
        common.left_click_object(Xvi_MainPage.acquire_Planar_View_Pane)
    elif viewType == ViewType.MotionView:
        common.left_click_object(Xvi_MainPage.acquire_Motion_View_Pane)
    elif viewType == ViewType.VolumeView:
        common.left_click_object(Xvi_MainPage.acquire_Volume_View_Pane)
